/** Exact canonical input only. Query and blob URLs are generated by this host, never trusted from Markdown. */
export function createWorkspaceResourcePolicy(workspaceId: string, documentId: string, attachmentIds: readonly string[], options: { versionId?: string; previews?: ReadonlyMap<string, string> } = {}) {
  const allowed = new Set(attachmentIds.map(id => `/api/task-workspaces/${workspaceId}/documents/${documentId}/attachments/${id}/content`));
  return { disableLinks: true, resolveImage(source: string): string | null {
    if (!allowed.has(source)) return null;
    return options.previews?.get(source) ?? (options.versionId ? `${source}?versionId=${encodeURIComponent(options.versionId)}` : source);
  } };
}
